// FUNCTION: BFME2 0x004B901D size=118 name=?onCreate@GrantUpgradeCreate@@UAEXXZ evidence=N:ledger
void GrantUpgradeCreate::onCreate()
{
	const GrantUpgradeCreateModuleData *data = (const GrantUpgradeCreateModuleData *)getModuleData();
	if (data->m_giveOnBuildComplete)
		return;
	ObjectStatusMaskType currentStatus = getObject()->m_status;
	if (data->m_exemptStatus.test(OBJECT_STATUS_UNDER_CONSTRUCTION))
	{
		if (!currentStatus.test(OBJECT_STATUS_UNDER_CONSTRUCTION))
		{
			const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgrade(((const GrantUpgradeCreateModuleData *)getModuleData())->m_upgradeToGrant);
			if (upgrade)
			{
				if (upgrade->getUpgradeType() == UPGRADE_TYPE_PLAYER)
				{
					Player *player = getObject()->getControllingPlayer();
					player->addUpgrade(upgrade, UPGRADE_STATUS_COMPLETE, 0);
				}
				else
					getObject()->giveUpgrade(upgrade);
			}
		}
	}
}

// FUNCTION: BFME2 0x004B9093 size=78 name=?onBuildComplete@GrantUpgradeCreate@@UAEXXZ evidence=N:ledger
void GrantUpgradeCreate::onBuildComplete()
{
	if (!shouldDoOnBuildComplete())
		return;
	const GrantUpgradeCreateModuleData *data = (const GrantUpgradeCreateModuleData *)getModuleData();
	m_needToRunOnBuildComplete = false;
	const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgrade(data->m_upgradeToGrant);
	if (upgrade)
	{
		if (upgrade->getUpgradeType() == UPGRADE_TYPE_PLAYER)
		{
			Player *player = getObject()->getControllingPlayer();
			player->addUpgrade(upgrade, UPGRADE_STATUS_COMPLETE, 0);
		}
		else
			getObject()->giveUpgrade(upgrade);
	}
}

